package com.acme.time;

import static org.junit.jupiter.api.Assertions.*;

import java.time.Duration;
import org.junit.jupiter.api.Test;

class DurationParserTest {
    @Test void parsesHours() { assertEquals(Duration.ofHours(2), DurationParser.parse("2h")); }
    @Test void parsesMinutes() { assertEquals(Duration.ofMinutes(45), DurationParser.parse("45m")); }
    @Test void parsesCombined() { assertEquals(Duration.ofMinutes(90), DurationParser.parse("1h30m")); }
    @Test void rejectsBlank() { assertThrows(IllegalArgumentException.class, () -> DurationParser.parse(" ")); }
    @Test void rejectsNegative() { assertThrows(IllegalArgumentException.class, () -> DurationParser.parse("-5m")); }
    @Test void rejectsGarbage() { assertThrows(IllegalArgumentException.class, () -> DurationParser.parse("soon")); }
}
